const u8* find(u32 codepoint)
{
    // 字数很少（几十到一两百），顺序查找完全够用，不必上二分
    for (int i = 0; i < glyph_count; ++i) {
        if (codepoints[i] == codepoint) {
            return bitmaps[i];
        }
    }
    return nullptr;
}

